        with open(full_path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            next(reader)  # Skip header
            data_rows = sum(1 for _ in reader)
            if data_rows < min_rows:
                return False, f"CSV has fewer than {min_rows} data rows: {filepath}"
            return True, f"CSV has {data_rows} data rows: {filepath}"
    except Exception as e:
        return False, f"Error reading CSV data: {filepath} - {str(e)}"


def check_numeric_columns(filepath, numeric_cols):
    """Check that specified columns contain valid numeric values."""
    full_path = os.path.join(OUTPUTS_DIR, filepath)
    try:
        with open(full_path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader)
            col_indices = {col: i for i, col in enumerate(header) if col in numeric_cols}

            for line_num, row in enumerate(reader, start=2):
                for col, idx in col_indices.items():
                    if idx < len(row):
                        try:
                            float(row[idx])
                        except ValueError:
                            return False, f"Non-numeric value in {filepath} at row {line_num}, column '{col}': {row[idx]}"
        return True, f"All numeric columns validated: {filepath}"
    except Exception as e:
        return False, f"Error validating numeric columns: {filepath} - {str(e)}"


def validate_outputs():
    """Run all validations and return results."""
    results = []

    # Check 1: t01_selected_indicators.csv exists and is non-empty
    passed, msg = check_file_exists("t01_selected_indicators.csv")
    results.append({
        "check_name": "t01_file_exists_and_nonempty",
        "passed": passed,
        "message": msg
    })

    # Check 2: t01_selected_indicators.csv has expected columns
    if passed:
        passed, msg = check_csv_has_expected_columns(
            "t01_selected_indicators.csv",
            ["indicator_id", "indicator_name", "theme", "justification", "expected_direction"]
        )
        results.append({
            "check_name": "t01_has_expected_columns",
            "passed": passed,
            "message": msg
        })

    # Check 3: t05_clean_stops.csv exists and is non-empty
    passed, msg = check_file_exists("t05_clean_stops.csv")
    results.append({
        "check_name": "t05_file_exists_and_nonempty",
        "passed": passed,
        "message": msg
    })

    # Check 4: t05_clean_stops.csv has expected columns
    if passed:
        passed, msg = check_csv_has_expected_columns(
            "t05_clean_stops.csv",
            ["stop_id", "stop_name", "stop_lat", "stop_lon"]
        )
        results.append({
            "check_name": "t05_has_expected_columns",
            "passed": passed,
            "message": msg
        })

    # Check 5: t05_clean_stops.csv has data rows
    if passed:
        passed, msg = check_data_rows("t05_clean_stops.csv", min_rows=1)
        results.append({
            "check_name": "t05_has_data_rows",
            "passed": passed,
            "message": msg
        })

    # Check 6: t08_pois_clean.csv exists and is non-empty
    passed, msg = check_file_exists("t08_pois_clean.csv")
    results.append({
        "check_name": "t08_file_exists_and_nonempty",
        "passed": passed,
        "message": msg
    })

    # Check 7: t08_pois_clean.csv has expected columns
    if passed:
        passed, msg = check_csv_has_expected_columns(
            "t08_pois_clean.csv",
            ["qid", "label", "poi_type", "latitude", "longitude", "source"]
        )
        results.append({
            "check_name": "t08_has_expected_columns",
            "passed": passed,
            "message": msg
        })

    # Check 8: t10_accessibility_scores.csv exists and is non-empty
    passed, msg = check_file_exists("t10_accessibility_scores.csv")
    results.append({
        "check_name": "t10_file_exists_and_nonempty",
        "passed": passed,
        "message": msg
    })

    # Check 9: t10_accessibility_scores.csv has expected columns
    if passed:
        passed, msg = check_csv_has_expected_columns(
            "t10_accessibility_scores.csv",
            ["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"]
        )
        results.append({
            "check_name": "t10_has_expected_columns",
            "passed": passed,
            "message": msg
        })

    # Check 10: t10_accessibility_scores.csv has numeric columns
    if passed:
        passed, msg = check_numeric_columns(
            "t10_accessibility_scores.csv",
            ["distance_m", "n_departures", "n_routes", "accessibility_score"]
        )
        results.append({
            "check_name": "t10_numeric_columns_valid",
            "passed": passed,
            "message": msg
        })

    # Check 11: t13_city_clusters.csv exists and is non-empty
    passed, msg = check_file_exists("t13_city_clusters.csv")
    results.append({
        "check_name": "t13_file_exists_and_nonempty",
        "passed": passed,
        "message": msg
    })

    # Check 12: t13_city_clusters.csv has expected columns
    if passed:
        passed, msg = check_csv_has_expected_columns(
            "t13_city_clusters.csv",
            ["city_id", "city_name", "year", "cluster_id"]
        )
        results.append({
            "check_name": "t13_has_expected_columns",
            "passed": passed,
            "message": msg
        })

    return results


def main():
    """Main entry point."""
    results = validate_outputs()

    # Write results to JSON file
    output_path = os.path.join(OUTPUTS_DIR, "t14_validation_summary.json")
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    # Print summary to stdout
    passed_count = sum(1 for r in results if r["passed"])
    print(f"Validation complete. {passed_count}/{len(results)} checks passed.")
    print(f"Results written to: {output_path}")

    # Exit with error code if any check failed
    if passed_count < len(results):
        sys.exit(1)
    sys.exit(0)


if __name__ == "__main__":
    main()

